import math
X=0.0;Y=0.0;TH=0.0
phase='fwd'
L1=2.75;H=1.05;L2=2.6
A=175.0
C0=(-5.32,0.42)
lastp=-10
woke=False
stuck=0.0
def wrap(a):
    return (a+180.0)%360.0-180.0
def cl(v,a,b):
    return max(a,min(b,v))
def tw(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py, Y+s*px+c*py)
def control(obs):
    global X,Y,TH,phase,lastp,woke,stuck
    dt=obs.get('dt',0.1) or 0.1
    mot=obs['motion']; v=mot['v_mps']; st=obs['steer_deg']
    X+=v*math.cos(TH)*dt; Y+=v*math.sin(TH)*dt
    TH+=v*math.tan(math.radians(st))/L1*dt
    phi=obs['hitch_deg']
    rr=obs['rig']['trailer_rear']
    rear=tw(rr[0],rr[1])
    R=wrap(math.degrees(TH)+180.0-phi)
    t=obs.get('t',0)
    ua=math.radians(A); u=(math.cos(ua),math.sin(ua)); nL=(-math.sin(ua),math.cos(ua))
    dx=rear[0]-C0[0]; dy=rear[1]-C0[1]
    lat=dx*nL[0]+dy*nL[1]; s=dx*u[0]+dy*u[1]
    if phase=='fwd':
        if X>=3.5 and abs(phi)<4:
            phase='rev'
        elif X>=5.0:
            phase='rev'
        else:
            if t-lastp>=1:
                lastp=t; print('F t%.1f X%.2f Y%.2f phi%.0f' % (t,X,Y,phi))
            return (0.0,1.0,-23)
    if abs(phi)>45 or obs.get('status')=='JACKKNIFED':
        phase='fwd'; X=min(X,0.0)
    Rdes=A-cl(12.0*lat,-15,15)
    e=wrap(Rdes-R)
    pd=cl(-0.9*e,-20,20)
    pr=math.radians(pd)
    ff=math.degrees(math.atan(L1*math.sin(pr)/(L2+H*math.cos(pr))))
    steer=cl(ff+2.5*(phi-pd),-34,34)
    sp=-0.6
    if s>3.9:
        sp=0.0
        if not woke:
            woke=True; wake('at bay end, not finished')
    if mot.get('hold_s',0)<=0 and abs(v)<0.05 and sp!=0: stuck+=dt
    else: stuck=0.0
    if stuck>3 and not woke:
        woke=True; wake('not moving')
    if t-lastp>=1:
        lastp=t
        print('R t%.1f R%.0f Rd%.0f phi%.0f pd%.0f st%.0f lat%.2f s%.2f' % (t,R,Rdes,phi,pd,steer,lat,s))
    return (steer,sp,-23)

