import math
X=0.0;Y=0.0;H=0.0
pts={}
tgt=None
mode='scan'
seq=[140,64,-64,-140,-64,64]
si=0
dwell=None
prevd=0.0
touches=0
fwd_until=0.0
lastp=-10

def clamp(a,lo,hi):
    return max(lo,min(hi,a))

def control(obs):
    global X,Y,H,tgt,mode,si,dwell,prevd,touches,fwd_until,lastp
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; st=math.radians(obs['steer_deg'])
    H+=v/2.5*math.tan(st)*dt
    X+=v*math.cos(H)*dt; Y+=v*math.sin(H)*dt
    cH=math.cos(H); sH=math.sin(H)
    def w(px,py):
        return (X+px*cH-py*sH, Y+px*sH+py*cH)
    views=obs.get('views') or {}
    for name,vw in views.items():
        try:
            o=vw['origin']
            for b,d in vw.get('walls',[]):
                if d>14: continue
                br=math.radians(b)
                wx,wy=w(o[0]+d*math.cos(br),o[1]+d*math.sin(br))
                pts[(round(wx/0.3),round(wy/0.3))]=(wx,wy)
        except Exception:
            pass
    rig=obs['rig']
    tg=obs.get('target') or {}
    try:
        if tg.get('in_sight') and tg.get('bearing_deg') is not None:
            e=rig['eye']; br=math.radians(tg['bearing_deg']); d=tg['dist_m']
            p=w(e[0]+d*math.cos(br),e[1]+d*math.sin(br))
            if tgt is None: tgt=p
            else:
                k=0.2 if d>8 else 0.4
                tgt=(tgt[0]+k*(p[0]-tgt[0]),tgt[1]+k*(p[1]-tgt[1]))
    except Exception:
        pass
    # head
    hd=obs['head']
    look=seq[si]
    if hd.get('settled') and abs(hd['gaze_deg']-look)<3:
        if dwell is None: dwell=t
        if t-dwell>0.5:
            si=(si+1)%len(seq); dwell=None; look=seq[si]
    else:
        dwell=None
    hitch=obs['hitch_deg']
    status=obs.get('status')
    tc=obs['counters']['touches']
    if tc>touches:
        touches=tc; mode='fwd'; fwd_until=t+1.5
        try: wake('touch at t=%.1f hitch %.0f'%(t,hitch))
        except Exception: pass
    if mode=='scan':
        if t>1.8: mode='rev'
        return (0.0,0.0,look)
    if mode=='rev' and (abs(hitch)>48 or status=='JACKKNIFED'):
        mode='fwd'; fwd_until=t+1.0
    if mode=='fwd':
        if abs(hitch)<8 and t>fwd_until:
            mode='rev'
        else:
            return (0.0,1.0,look)
    tr=rig['trailer_rear']; th=rig['trailer_heading_deg']
    Rx,Ry=w(tr[0],tr[1])
    thb=H+math.radians(th)+math.pi
    near=[p for p in pts.values() if abs(p[0]-Rx)<14 and abs(p[1]-Ry)<14]
    tdel=None
    if tgt is not None:
        dx=tgt[0]-Rx; dy=tgt[1]-Ry
        if math.hypot(dx,dy)<12:
            a=math.atan2(dy,dx)-thb
            tdel=math.degrees(math.atan2(math.sin(a),math.cos(a)))
    best=None; bd=0
    for dd in range(-50,51,5):
        a=thb+math.radians(dd); ux=math.cos(a); uy=math.sin(a)
        F=12.0; cl=3.0; cr=3.0
        for (px,py) in near:
            dx=px-Rx; dy=py-Ry
            al=dx*ux+dy*uy
            if al<-0.5 or al>12: continue
            c=ux*dy-uy*dx
            if al>0.3 and abs(c)<1.5:
                if al<F: F=al
            elif al<6:
                if c>0:
                    if c<cl: cl=c
                else:
                    if -c<cr: cr=-c
        s=F+1.5*min(cl,cr)-0.03*abs(dd)-0.02*abs(dd-prevd)
        if tdel is not None: s-=0.06*abs(dd-tdel)
        if best is None or s>best: best=s; bd=dd
    prevd=0.6*prevd+0.4*bd
    hd_des=clamp(-0.9*prevd,-35,35)
    steer=clamp(2.0*(hitch-hd_des),-45,45)
    if t-lastp>3:
        lastp=t
        print('t%.1f R(%.1f,%.1f) hitch%.0f des%.0f d%.0f n%d tgt%s'%(t,Rx,Ry,hitch,hd_des,prevd,len(near),str(tdel)))
    return (steer,-0.8,look)

