    steer=clamp(2.0*(hitch-hd_des),-45,45)
    if t-lastp>3:
        lastp=t
        print('t%.1f R(%.1f,%.1f) h%.0f des%.0f cp%s cn%s e%.0f tg%s'%(t,Rx,Ry,hitch,hd_des,str(cpos and round(cpos,1)),str(cneg and round(cneg,1)),ef,str(tdel and round(tdel))))
    return (steer,-0.6,look)

