def clamp(a,lo,hi):
    return max(lo,min(hi,a))

def proj(path,px,py):
    best=None;bs=0.0;s0=0.0
    for i in range(len(path)-1):
        ax,ay=path[i];bx,by=path[i+1]
        dx=bx-ax;dy=by-ay;L=math.hypot(dx,dy)
        u=clamp(((px-ax)*dx+(py-ay)*dy)/(L*L),0,1)
        qx=ax+u*dx;qy=ay+u*dy
        d=math.hypot(px-qx,py-qy)
        if best is None or d<best: best=d;bs=s0+u*L
        s0+=L
    return bs,best

def at(path,s):
    s0=0.0
    for i in range(len(path)-1):
        ax,ay=path[i];bx,by=path[i+1]
        L=math.hypot(bx-ax,by-ay)
        if s<=s0+L:
            u=(s-s0)/L
            return (ax+u*(bx-ax),ay+u*(by-ay))
        s0+=L
    return path[-1]

def control(obs):
    global X,Y,H,mode,fstart,touches,tgt,lastp,ef,PATH
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; st=math.radians(obs['steer_deg'])
    H+=v/2.5*math.tan(st)*dt
    X+=v*math.cos(H)*dt; Y+=v*math.sin(H)*dt
    cH=math.cos(H); sH=math.sin(H)
