            mode='rev'
        else:
            hdes=math.atan2(YC-Y,5.0)
            s=clamp(1.5*math.degrees(hdes-H),-20,20)
            return (s,1.2,look)
    if mode=='fwd2':
        if fstart is None: fstart=X
        if math.hypot(X-fstart,0)>2.0 and abs(hitch)<12 or abs(X-fstart)>4.0:
            mode='rev'
        else:
            return (clamp(-0.8*hitch,-25,25),0.8,look)
    tr=rig['trailer_rear']; th=rig['trailer_heading_deg']
    Rx,Ry=w(tr[0],tr[1])
    thb=H+math.radians(th)+math.pi
    s,dev=proj(PATH,Rx,Ry)
    Lx,Ly=at(PATH,s+4.5)
    a=math.atan2(Ly-Ry,Lx-Rx)-thb
    e=math.degrees(math.atan2(math.sin(a),math.cos(a)))
    ef=0.5*ef+0.5*e
    hd_des=clamp(-1.2*ef,-30,30)
    steer=clamp(2.2*(hitch-hd_des),-45,45)
    spd=-0.6
    if tgt is not None and math.hypot(tgt[0]-Rx,tgt[1]-Ry)<5: spd=-0.4
    if t-lastp>2.0:
        lastp=t
        print('t%.1f %s X%.1f Y%.1f H%.0f R(%.1f,%.1f) dev%.1f h%.0f des%.0f e%.0f tgt%s'%(t,mode,X,Y,math.degrees(H),Rx,Ry,dev,hitch,hd_des,ef,str(tgt and (round(tgt[0],1),round(tgt[1],1)))))
    return (steer,spd,look)

