import math
G=[-30,-90,-150,30,90,150]
S={'i':0,'t0':None,'pts':{},'done':False}
def control(obs):
    t=obs['t']
    if S['done']:
        return (0.0,0.0,130.0)
    g=G[S['i']]
    h=obs['head']
    vs=obs.get('views') or {}
    if h.get('settled') and abs(h['gaze_deg']-g)<3 and vs:
        for name,vw in vs.items():
            if not vw: continue
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                x=ox+d*math.cos(math.radians(b)); y=oy+d*math.sin(math.radians(b))
                if d<5.0:
                    S['pts'][(round(x*5),round(y*5))]=(round(x,2),round(y,2),name[0])
        S['i']+=1
        if S['i']>=len(G):
            S['done']=True
            p=sorted(S['pts'].values())
            print('PTS '+' '.join('%.2f,%.2f%s'%q for q in p))
            wake('scan done')
            return (0.0,0.0,130.0)
    return (0.0,0.0,float(G[min(S['i'],len(G)-1)]))

